#!/bin/bash
if [ "$EUID" -ne 0 ]; then
  echo "Ejecuta como root: sudo -i"
  exit 1
fi

export DEBIAN_FRONTEND=noninteractive
export NEEDRESTART_MODE=a

echo "[+] Instalando paquetes base..."
apt-get update -y && apt-get upgrade -y
apt-get install -y python3 python3-pip curl wget git net-tools iptables build-essential cmake nano lsof dropbear stunnel4 unzip jq lsb-release tar

echo "[+] Descomprimiendo la suite completa RUSSO NETFREE..."
TMP_TAR=$(mktemp)
tail -n +52 "$0" | base64 -d > "$TMP_TAR"
tar -xzvf "$TMP_TAR" -C /
rm -f "$TMP_TAR"

cat << 'CMD' > /usr/bin/menu
#!/bin/bash
cd /etc/adm-lite && ./menu
CMD

cat << 'CMD' > /usr/bin/adm
#!/bin/bash
cd /etc/adm-lite && ./menu
CMD

# Crear enlace simbólico y corregir permisos
mkdir -p /usr/bin/ejecutar /etc/adm-lite
ln -sfn /usr/bin/ejecutar /bin/ejecutar

sed -i 's/\r$//' /usr/bin/menu /usr/bin/adm /etc/adm-lite/* /usr/bin/ejecutar/* 2>/dev/null
chmod +x /usr/bin/menu /usr/bin/adm
chmod -R 755 /etc/adm-lite /usr/bin/ejecutar /bin/ejecutar

clear
echo "=========================================="
echo " ¡INSTALACIÓN COMPLETA Y EXITOSA!         "
echo "=========================================="
echo ""
echo " Escribe 'menu' o 'adm' para iniciar."
echo ""
exit 0
